	'messages:interwiki_prefix' => 'en:Prefix',
	'messages:interwiki-prefix-label' => 'en:Prefix:',
	'messages:interwiki_prefix_intro' => 'en:Interwiki prefix to be used in <code>[<nowiki />[prefix:<em>pagename</em>]]</code> wikitext syntax.',
	'messages:interwiki_url' => 'en:URL',
	'messages:interwiki-url-label' => 'en:URL:',
	'messages:interwiki_url_intro' => 'en:Template for URLs. The placeholder $1 will be replaced by the <em>pagename</em> in <code>[<nowiki />[prefix:<em>pagename</em>]]</code>.',
	'messages:interwiki-api-label' => 'en:API:',
	'messages:interwiki_local' => 'en:Forward',
	'messages:interwiki-local-label' => 'en:Forward',
	'messages:interwiki_local_0_intro' => 'en:External HTTP requests to the local wiki using this interwiki prefix in the URL will result in a "{{int:badtitle}}" error page.',
	'messages:interwiki_local_1_intro' => 'en:External HTTP requests to the local wiki using this interwiki prefix will be redirected to the target URL of the interwiki (i.e. treated like links to local pages).',
	'messages:interwiki_trans' => 'en:Transclude',
	'messages:interwiki-trans-label' => 'en:Transclude',
	'messages:interwiki_trans_1_intro' => 'en:If wikitext syntax <code>{<nowiki />{prefix:<em>pagename</em>}}</code> is used, allow template/page transclusion from the foreign wiki if interwiki transclusions are enabled in general ([https://www.mediawiki.org/wiki/Special:MyLanguage/Manual:$wgEnableScaryTranscluding scary transclusion]).',
	'messages:interwiki_trans_0_intro' => 'en:Do not allow <code>{<nowiki />{prefix:<em>pagename</em>}}</code> to transclude foreign templates/pages, rather look for a local page in the template namespace.',
	'messages:interwiki_error' => 'en:Error: The interwiki table is empty, or something else went wrong.',
